"""Prepare a third isolated native-core service. No SDK, Guest or service starts.

The printed root block creates only the exact NEW transient unit after review.
The audited proxy/namespace/health library is pinned and staged in the new root.
"""
import argparse,base64,hashlib,json,os,re,secrets,socket,stat,struct,subprocess,sys,types
from pathlib import Path

