def old_state(m):
    result={}
    for unit in OLD_UNITS:
        row=m.properties(unit);need(row.get('ActiveState')=='active' and int(row.get('MainPID','0'))>1,'An existing service is not active; no recovery attempted')
        pid=int(row['MainPID']);ticks=Path('/proc/'+str(pid)+'/stat').read_text().rsplit(')',1)[1].split()[19]
        result[unit]=[pid,ticks]
    m.http_health(18080);m.http_health(18081)
    return result


def adapter(definition):
    # Reuses only the audited library, with a fixed immutable new-service definition.
    return ("import base64,hashlib,json,sys\nfrom pathlib import Path\n"+
            "p=Path("+repr(str(D/'libexec/native_prepare.py'))+");raw=p.read_bytes()\n"+
            "if hashlib.sha256(raw).hexdigest()!="+repr(definition['prepareSourceSha256'])+":raise RuntimeError('Native adapter dependency changed')\n"+
            "scope={'__name__':'native_adapter','__file__':str(p)};exec(compile(raw,str(p),'exec'),scope)\n"+
            "scope['runtime_entry']("+repr(definition)+",sys.argv[1:])\n").encode()


def runtime_entry(definition,argv):
    need(argv and argv[0] in ('inside','proxy-inside','proxy-host','health'),'Unexpected runtime adapter mode')
    m=make_module(definition);m.identity()
    need(digest(own(D/'definition-native.json',1024**2))==definition['definitionSha256'],'Native definition changed')
    if definition.get('rootfsBinding'):
        need(digest(own(definition['rootfsBinding']['path'],2*1024**2))==definition['rootfsBinding']['sha256'],'Native rootfs binding changed')
    if argv[0]=='inside':
        try:m.inside()
        except BaseException:
            import traceback
            with (D/'logs/launcher.log').open('a') as log:traceback.print_exc(file=log)
            raise
        return
    if argv[0].startswith('proxy-'):
        import asyncio
        asyncio.run(m.proxy(argv[0].split('-',1)[1]));return
    m.no_caps();before=old_state(m)
    result=m.health('--post-disconnect' in argv)
    need(old_state(m)==before,'An existing service changed during native health')
    result.update(activate='source '+str(D/'cli/env.sh'),CLI=str(D/'cli/bin/aenv-native'),
        existing_services_unchanged=True,nativeGuestBindingsConfigured=bool(definition.get('rootfsBinding')),
        Guest_or_DAX_acceptance=False,SDK_called=False)
    print('BEGIN_NATIVE_HEALTH_REPORT');print(json.dumps(result,indent=2));print('END_NATIVE_HEALTH_REPORT')


def root_block(pins,boot_id,old):
    code="""import hashlib,json,os,socket,stat,subprocess
from pathlib import Path
assert os.geteuid()==0 and os.uname().nodename=='server1','A root only'
assert Path('/proc/sys/kernel/random/boot_id').read_text().strip()==BOOT,'Boot changed'
assert subprocess.check_output(['/usr/bin/id','-u','jwk'],text=True).strip()=='1204'
assert subprocess.check_output(['/usr/bin/id','-g','jwk'],text=True).strip()=='1205'
for name,gid in [('kvm','36'),('aenv','982')]:
 assert subprocess.check_output(['/usr/bin/getent','group',name],text=True).split(':')[2]==gid
for unit,identity in OLD.items():
 fields=dict(x.split('=',1) for x in subprocess.check_output(['/usr/bin/systemctl','show',unit,'--property=ActiveState,MainPID'],text=True).splitlines() if '=' in x)
 assert fields.get('ActiveState')=='active' and int(fields['MainPID'])==identity[0],'Existing unit changed'
 assert Path('/proc/'+fields['MainPID']+'/stat').read_text().rsplit(')',1)[1].split()[19]==identity[1]
assert subprocess.check_output(['/usr/bin/systemctl','show',UNIT,'--property=LoadState','--value'],text=True).strip()=='not-found','New unit already exists; preserved'
for name,expected in PINS.items():
 p=Path(name);assert p.resolve(strict=True)==p
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK);before=os.fstat(fd)
 assert stat.S_ISREG(before.st_mode) and before.st_uid==1204 and before.st_size<=512*1024**2
 h=hashlib.sha256()
 with os.fdopen(fd,'rb') as f:
  for block in iter(lambda:f.read(1024**2),b''):h.update(block)
  after=os.fstat(f.fileno())
 assert (before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns)
 assert h.hexdigest()==expected,'Reviewed new-service input changed'
assert Path('/sys/module/ublk_drv').is_dir()
assert all(Path(p).is_char_device() for p in ('/dev/kvm','/dev/ublk-control','/dev/net/tun'))
with socket.socket() as s:s.bind(('127.0.0.1',18082))
command=['/usr/bin/systemd-run','--unit='+UNIT,'--collect','--property=Description=AgentENV native CoW A experiment',
 '--property=User=jwk','--property=Group=jwk','--property=SupplementaryGroups=kvm aenv',
 '--property=CapabilityBoundingSet=CAP_SYS_ADMIN CAP_NET_ADMIN','--property=AmbientCapabilities=CAP_SYS_ADMIN CAP_NET_ADMIN',
 '--property=NoNewPrivileges=yes','--property=RestrictSUIDSGID=yes','--property=PrivateNetwork=yes','--property=PrivateMounts=yes',
 '--property=Type=exec','--property=Restart=no','--property=KillMode=control-group','--property=TimeoutStopSec=90s',
 '--property=LimitNOFILE=65536','--property=LimitMEMLOCK=2147483648','--property=WorkingDirectory='+DEPLOYMENT,'--property=StandardOutput=null','--property=StandardError=null',
 '/usr/bin/python3','-I','-B',LAUNCHER,'inside']
subprocess.run(command,check=True)
print('ONLY_NEW_NATIVE_UNIT_SUBMITTED_RUN_JWK_HEALTH_NEXT')
"""
    literals='BOOT='+repr(boot_id)+'\nOLD='+repr(old)+'\nPINS='+repr(pins)+'\nUNIT='+repr(UNIT)+'\nDEPLOYMENT='+repr(str(D))+'\nLAUNCHER='+repr(str(D/'libexec/native_service.py'))+'\n'
    return "/usr/bin/python3 -I -B - <<'NATIVE_NEW_UNIT_REVIEWED_ROOT'\n"+literals+code+"NATIVE_NEW_UNIT_REVIEWED_ROOT\n"



def validated_builtin_fc(report_path):
    need(report_path==ROOT/'builds/fc-gnu-integrated-v1/return.json','Use reviewed builtin FC build report')
    fc=read_json(report_path)
    need(fc.get('status')=='FC_BUILT_WITH_MATCHING_EMBEDDED_POLICY_NOT_DEPLOYED'
         and fc.get('embeddedPolicySha256')==POLICY_SHA and fc.get('embeddedPolicyBytes')==2810
         and fc.get('externalFilterRequired') is False and fc.get('priorStagedBinaryUnchanged') is True
         and fc.get('priorSourceUnchanged') is True,'Built-in policy build receipt differs')
    path=ROOT/'builds/fc-gnu-integrated-v1/artifacts/firecracker'
    need(fc.get('firecracker')=={'path':str(path),'sha256':FC_SHA,'bytes':7626328},'Expected actual new FC artifact')
    binary(path,FC_SHA)
    guest_path=ROOT/'r/pm-a-v1/guest-builtin-policy-v1/return.json'
    need(fc.get('guestOutput')==str(guest_path.parent),'Built-in Guest evidence location differs')
    guest=read_json(guest_path)
    need(guest.get('revision')=='native-pmem-builtin-policy-v1'
         and guest.get('guestDaxSelftestPassed') is True and guest.get('firecrackerExit')==0
         and guest.get('timedOut') is False and guest.get('firecrackerReaped') is True
         and guest.get('safeToRetireThisLease') is True,'New FC default-policy Guest is not verified')
    need(guest.get('pinnedInputs',{}).get('firecracker')=={'sha256':FC_SHA,'bytes':7626328}
         and 'seccompFilter' not in guest['pinnedInputs'] and 'traceRunner' not in guest['pinnedInputs'],
         'Guest did not validate this binary without external policy or tracer')
    return path,{'firecracker':{'sha256':FC_SHA,'bytes':7626328}}

def prepare(args):
    need(sys.platform=='linux' and socket.gethostname()=='server1' and os.uname().machine=='aarch64','Use original ARM64 Linux A')
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary jwk without sudo')
    caps=dict(line.split(':',1) for line in Path('/proc/self/status').read_text().splitlines() if ':' in line)
    need(all(int(caps[k].strip(),16)==0 for k in ('CapInh','CapPrm','CapEff','CapAmb')),'Capability-free preparation required')
    core_path=Path(args.core_report);core=read_json(core_path)
    need(core.get('status')=='THREE_CORE_BINARIES_BUILT_STAGED_NOT_DEPLOYED' and core.get('sourceCommit')==COMMIT
         and core.get('sourceTree')=='93ef4bfec855ed0b68aa275caf9f9c769a13c76e','New core build receipt is not complete or differs')
    artifact_root=core_path.parent/'artifacts';binaries={}
    for name in ('server','aenv','uvm-ublk-daemon'):
        binaries[name]=core['artifacts'][name]['sha256'];binary(artifact_root/name,binaries[name])
    firecracker,fc_artifacts=validated_builtin_fc(Path(args.fc_report))
    tools=read_json(args.tools_report)
    need(tools.get('status')=='PRIVATE_TOOLS_IMAGE_PREPARED_NOT_GUEST_ACCEPTANCE' and tools.get('mode')=='runtime'
         and tools.get('originalUnchanged') is True and tools.get('lowerFilesystem')=='ext4','New runtime Guest tools are not ready')
    tools_image=Path(tools['imagePath']);tools_bytes=own(tools_image)
    need(digest(tools_bytes)==tools['image']['sha256'],'New tools image differs')
    definition={'binaries':binaries,'config':configuration(tools['toolsVersion']),'rootfsBinding':None}
    if args.rootfs_binding:
        binding=own(args.rootfs_binding,2*1024**2)
        need(re.fullmatch(r'[0-9a-f]{64}',args.binding_sha256 or '') and digest(binding)==args.binding_sha256,'Explicit rootfs binding pin differs')
        value=json.loads(binding);need(value.get('version')==2 and value.get('lowerFilesystem')=='ext4','Expected explicit native NC ext4 binding')
        definition['rootfsBinding']={'path':str(Path(args.rootfs_binding)),'sha256':args.binding_sha256}
    m=make_module(definition);m.identity();m.no_caps()
    old=old_state(m)
    receipt=read_json(LEGACY/'installation.json');master=LEGACY/'libexec/deploy_a_ub.py'
    need(digest(own(master,512*1024))==receipt['launcher_sha256'],'Installed legacy master no longer matches its receipt')
    for path in (D,RUNTIME,FC_WORK):
        need(path.resolve()==path and not path.exists() and not path.is_symlink(),'New deployment/runtime/work path already exists or redirected; preserved')
    need(digest(own(BASE/'deps/kernel/vmlinux-6.1.175/vmlinux.bin'))==KERNEL_SHA,'Original Guest kernel differs')
    prepare_raw=Path(__file__).read_bytes();definition['prepareSourceSha256']=digest(prepare_raw)
    public_definition={k:v for k,v in definition.items() if k!='prepareSourceSha256'}
    definition_raw=(json.dumps(public_definition,indent=2,sort_keys=True)+'\n').encode()
    definition['definitionSha256']=digest(definition_raw)
    m=make_module(definition);m.ARTIFACTS=artifact_root
    original_inputs=m.selected_inputs
    def selected():
        items=original_inputs()
        replacements={'deps/firecracker/1.15.1-patch-v3/firecracker':(firecracker,fc_artifacts['firecracker']['sha256'],0o750),
                      'deps/tools/0.1.1/tools.ext4':(tools_image,tools['image']['sha256'],0o640)}
        result=[]
        for relative,path,mode,expected in items:
            if relative.as_posix() in replacements:
                path,expected,mode=replacements[relative.as_posix()]
            result.append((relative,path,mode,expected))
        return result
    m.selected_inputs=selected
    def cli_files(key):
        for folder in ('cli/cache','cli/tmp'):m.mkdir(D/folder)
        script=('#!/bin/sh\nexport XDG_CONFIG_HOME="'+str(D/'cli/config')+'"\nexport XDG_CACHE_HOME="'+str(D/'cli/cache')+'"\nexport TMPDIR="'+str(D/'cli/tmp')+'"\nexport LD_LIBRARY_PATH="'+str(D/'native/lib')+':'+str(D/'native/fallback/lib')+'"\nunset http_proxy https_proxy HTTP_PROXY HTTPS_PROXY all_proxy ALL_PROXY\nexport NO_PROXY="127.0.0.1,localhost,::1"\nexport no_proxy="$NO_PROXY"\nexec "'+str(D/'bin/aenv')+'" "$@"\n').encode()
        m.put(D/'cli/bin/aenv-native',script,0o700)
        m.put(D/'cli/config/aenv/credentials',('url = "http://127.0.0.1:18082"\napi_key = '+json.dumps(key)+'\n').encode())
        m.put(D/'cli/env.sh',('export PATH="'+str(D/'cli/bin')+':$PATH"\nhash -r\n').encode())
    m.cli_files=cli_files
    def stage_launcher():
        m.put(D/'libexec/native_base.py',base64.b64decode(BASE_SOURCE_B64,validate=True))
        m.put(D/'libexec/native_prepare.py',prepare_raw)
        m.put(D/'definition-native.json',definition_raw)
        m.put(m.LAUNCHER,adapter(definition))
        return {'native_base.py':BASE_SOURCE_SHA,'native_prepare.py':digest(prepare_raw)}
    m.stage_launcher=stage_launcher
    result=m.install()
    m.mkdir(FC_WORK);m.mkdir(D/'logs/firecracker')
    need(old_state(m)==old,'An existing Runtime changed during native preparation')
    pins={str(D/relative):row['sha256'] for relative,row in read_json(D/'input-manifest.json').items()}
    for path in (D/'config/runtime.toml',D/'config/api-key',D/'installation.json',D/'definition-native.json',m.LAUNCHER,D/'libexec/native_base.py',D/'libexec/native_prepare.py',D/'cli/bin/aenv-native',D/'cli/config/aenv/credentials'):
        pins[str(path)]=digest(own(path))
    if definition['rootfsBinding']:pins[definition['rootfsBinding']['path']]=definition['rootfsBinding']['sha256']
    text=root_block(pins,Path('/proc/sys/kernel/random/boot_id').read_text().strip(),old)
    m.put(D/'review-new-unit-root.txt',text.encode())
    result.update(status='NATIVE_SERVICE_PREPARED_NOT_STARTED',unit=UNIT,api='http://127.0.0.1:18082',
                  CLI=str(D/'cli/bin/aenv-native'),existing_services_unchanged=True,
                  nativeGuestBindingsConfigured=bool(definition['rootfsBinding']),SDK_called=False,Guest_created=False,
                  runtimeSourceCommit=COMMIT,firecrackerCoreCommit='56005a7fb5cac5653429bfb37db356234a64c4b5',
                  firecrackerSha256=FC_SHA,builtinPolicyGuestPreviouslyPassed=True,
                  stageScope='New Runtime service preparation; no shared-rootfs activation or Guest creation',
                  rootReview=str(D/'review-new-unit-root.txt'),healthCommand='/usr/bin/python3 -I -B '+str(m.LAUNCHER)+' health',
                  postDisconnectCommand='/usr/bin/python3 -I -B '+str(m.LAUNCHER)+' health --post-disconnect')
    print('BEGIN_NATIVE_PREPARE_REPORT');print(json.dumps(result,indent=2));print('END_NATIVE_PREPARE_REPORT')
    print('REVIEW: only the NEW unit; CAP_SYS_ADMIN/CAP_NET_ADMIN are powerful and not confined to project paths. Existing services are untouched.')
    print('BEGIN_NEW_UNIT_ROOT_BLOCK_COPY_BODY_ONLY');print(text);print('END_NEW_UNIT_ROOT_BLOCK_COPY_BODY_ONLY')
    return 0


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('mode',nargs='?',choices=('plan','prepare'),default='plan')
    p.add_argument('--core-report');p.add_argument('--fc-report');p.add_argument('--tools-report')
    p.add_argument('--rootfs-binding');p.add_argument('--binding-sha256');args=p.parse_args()
    if args.mode=='plan':
        print(json.dumps({'status':'PLAN_ONLY_NO_WRITES','deployment':str(D),'unit':UNIT,'port':18082,'runtime':str(RUNTIME),
                         'requires':['complete new core build receipt','complete native FC result/stage receipts','runtime ext4 Guest-tools receipt'],
                         'SDK_called':False,'Guest_created':False,'services_changed':False},indent=2));return 0
    try:
        need(all((args.core_report,args.fc_report,args.tools_report)),'Supply all three completed build/tools reports')
        return prepare(args)
    except Exception as error:
        text=re.sub(r'e2b_[A-Za-z0-9._~-]+','<redacted>',str(error))
        print('BEGIN_NATIVE_PREPARE_REPORT');print(json.dumps({'status':'STOPPED_NATIVE_PREPARATION_NO_SERVICE_STARTED',
            'errorType':type(error).__name__,'reason':text[:1200],'SDK_called':False,'Guest_created':False,'services_changed':False,
            'preserve_new_partial_directory_if_present':str(D)},indent=2));print('END_NATIVE_PREPARE_REPORT');return 1


if __name__=='__main__':raise SystemExit(main())
